import{_ as t,o as i,c as a,ae as n}from"./chunks/framework.BONZgKEB.js";const d=JSON.parse('{"title":"Competition Setup & Scheduling","description":"","frontmatter":{},"headers":[],"relativePath":"guide/competition-setup.md","filePath":"guide/competition-setup.md"}'),o={name:"guide/competition-setup.md"};function s(r,e,l,h,g,c){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="competition-setup-scheduling" tabindex="-1">Competition Setup &amp; Scheduling <a class="header-anchor" href="#competition-setup-scheduling" aria-label="Permalink to &quot;Competition Setup &amp; Scheduling&quot;">​</a></h1><p>After successfully creating an event and registering athletes, the next step is to configure the competitions. A single event is often divided into multiple competitions based on equipment and gender (e.g., Recurve Men, Compound Women).</p><h2 id="_1-understanding-competitions" tabindex="-1">1. Understanding Competitions <a class="header-anchor" href="#_1-understanding-competitions" aria-label="Permalink to &quot;1. Understanding Competitions&quot;">​</a></h2><p>Navigate to the <strong>Competitions</strong> tab within your Event Dashboard. Here you will see a list of all active competitions for your event.</p><p>Selecting a specific competition will take you to the <strong>Competition Dashboard</strong>, where you manage the two main phases of an archery tournament:</p><ol><li><strong>Qualification Round</strong></li><li><strong>Elimination Round</strong></li></ol><h2 id="_2-setup-qualification-shooting" tabindex="-1">2. Setup Qualification Shooting <a class="header-anchor" href="#_2-setup-qualification-shooting" aria-label="Permalink to &quot;2. Setup Qualification Shooting&quot;">​</a></h2><p>The Qualification round is where athletes shoot a set number of arrows to determine their ranking and seeding for the Elimination round.</p><h3 id="target-assignments" tabindex="-1">Target Assignments <a class="header-anchor" href="#target-assignments" aria-label="Permalink to &quot;Target Assignments&quot;">​</a></h3><p>Before scoring can begin, the host must assign athletes to specific targets on the field.</p><ol><li>Navigate to the <strong>Schedule</strong> or <strong>Setup</strong> section of your Competition.</li><li>Select <strong>Qualification Setup</strong>.</li><li>You will see a list of all registered athletes for this category.</li><li><strong>Assign Targets:</strong> Enter the Target ID (e.g., &quot;1A&quot;, &quot;2B&quot;) for each athlete. <ul><li><em>Tip: The application helps you organize athletes by ensuring no two athletes are assigned the exact same target position simultaneously.</em></li></ul></li><li><strong>Save Assignments:</strong> Once all athletes are assigned, click save.</li></ol><p>This assignment dictates which digital scoresheet the athlete or their assigned referee will have access to during the round.</p><h2 id="_3-setup-elimination-shooting" tabindex="-1">3. Setup Elimination Shooting <a class="header-anchor" href="#_3-setup-elimination-shooting" aria-label="Permalink to &quot;3. Setup Elimination Shooting&quot;">​</a></h2><p>Once the Qualification round is complete and all scores are finalized, the system can determine the athletes&#39; ranks. These ranks are used to seed the Elimination brackets.</p><h3 id="generating-brackets" tabindex="-1">Generating Brackets <a class="header-anchor" href="#generating-brackets" aria-label="Permalink to &quot;Generating Brackets&quot;">​</a></h3><ol><li>Ensure the Qualification round is marked as <strong>Completed</strong>.</li><li>Navigate to the <strong>Elimination Setup</strong> section.</li><li>Select the type of elimination format (e.g., Individual Elimination).</li><li><strong>Generate Bracket:</strong> The system will automatically build the match tree. The #1 ranked archer will be placed against the lowest-ranked archer, the #2 against the second lowest, and so on, following standard World Archery bracket rules.</li><li><strong>Review Matches:</strong> You can review the generated matchups before officially starting the Elimination round.</li></ol><h3 id="managing-byes" tabindex="-1">Managing Byes <a class="header-anchor" href="#managing-byes" aria-label="Permalink to &quot;Managing Byes&quot;">​</a></h3><p>If the number of athletes is not a perfect power of two (e.g., 16, 32, 64), the system will automatically assign <strong>Byes</strong> to the top-seeded athletes, allowing them to advance automatically to the next round.</p><p>👉 <em>Next Step:</em> <a href="./scoring-workflow.html">Learn about the Scoring Workflow</a></p>',19)])])}const p=t(o,[["render",s]]);export{d as __pageData,p as default};
